#!/bin/bash
# Uninstall script for TradingView Desktop
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling TradingView Desktop..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping TradingView Desktop if running..."
pkill -f "TradingView Desktop" 2>/dev/null || true

# Kill application with bundle ID com.tradingview.tradingviewapp.desktop if running
echo "Stopping application with bundle ID com.tradingview.tradingviewapp.desktop if running..."
killall -9 "com.tradingview.tradingviewapp.desktop" 2>/dev/null || true

# Remove /Applications/TradingView.app
echo "Removing /Applications/TradingView.app..."
if [ -d "/Applications/TradingView.app" ]; then
    rm -rf "/Applications/TradingView.app" 2>/dev/null || true
elif [ -f "/Applications/TradingView.app" ]; then
    rm -f "/Applications/TradingView.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/TradingView
echo "Removing $HOME/Library/Application Support/TradingView..."
if [ -d "$HOME/Library/Application Support/TradingView" ]; then
    rm -rf "$HOME/Library/Application Support/TradingView" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/TradingView" ]; then
    rm -f "$HOME/Library/Application Support/TradingView" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.tradingview.tradingviewapp.desktop.plist
echo "Removing $HOME/Library/Preferences/com.tradingview.tradingviewapp.desktop.plist..."
if [ -d "$HOME/Library/Preferences/com.tradingview.tradingviewapp.desktop.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.tradingview.tradingviewapp.desktop.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.tradingview.tradingviewapp.desktop.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.tradingview.tradingviewapp.desktop.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/com.tradingview.tradingviewapp.desktop.savedState
echo "Removing $HOME/Library/Saved Application State/com.tradingview.tradingviewapp.desktop.savedState..."
if [ -d "$HOME/Library/Saved Application State/com.tradingview.tradingviewapp.desktop.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/com.tradingview.tradingviewapp.desktop.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/com.tradingview.tradingviewapp.desktop.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/com.tradingview.tradingviewapp.desktop.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
